import subprocess,time,json,statistics,hashlib
from pathlib import Path
T=Path('/tmp/unisacc-v009-integrated');R=Path('/Users/wjc/repos/unisacc')
c=T/'candidate.com';released=R/'unisacc.com';raw=c.read_bytes();n=int.from_bytes(raw[-8:],'little');prefix=raw[:-16-n]
r=released.read_bytes();m=int.from_bytes(r[-8:],'little');old=r[-16-m:-16]
plain=T/'plain.com';plain.write_bytes(prefix+old+b'UNIPKG1\n'+len(old).to_bytes(8,'little'))
minimal=T/'minimal.c';minimal.write_text('int main(void){return 0;}\n')
exes={'plain':plain,'compressed':c,'released':released};results={}
def call(args):
 start=time.perf_counter_ns();p=subprocess.run(list(map(str,args)),capture_output=True,timeout=15)
 dt=(time.perf_counter_ns()-start)/1e6
 assert p.returncode==0,(args,p.returncode,p.stderr);assert not p.stderr,p.stderr
 return p.stdout,dt
for label,source in [('calc',R/'examples/apps/calc.c'),('startup',minimal)]:
 values={k:[] for k in exes};expected=None
 for exe in exes.values():call(['sh',exe,'-run',source])
 for i in range(5):
  order=list(exes);order=order[i%3:]+order[:i%3]
  for k in order:
   out,dt=call(['sh',exes[k],'-run',source]);values[k].append(dt)
   if expected is None:expected=out
   assert out==expected
 results[label]={'trials_ms':values,'median_ms':{k:statistics.median(v) for k,v in values.items()},'stdout_equal':True}
images=[]
for target in ['lnx/arm64','lnx/x86_64','osx/arm64','osx/x86_64','win/arm64','win/x86_64']:
 out,_=call(['sh',c,'-O2','-b',target,R/'examples/hello.c'])
 ref,_=call(['/tmp/unisacc-release-v008/ref','-O2','-b',target,R/'examples/hello.c'])
 assert out==ref,target;images.append({'target':target,'bytes':len(out),'sha256':hashlib.sha256(out).hexdigest()})
results['images']=images;results['artifacts']={k:{'bytes':len(p.read_bytes()),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for k,p in exes.items()}
(T/'bench.json').write_text(json.dumps(results,indent=2)+'\n');print(json.dumps(results,indent=2))
